-- Carga de catalogo.especies (enriquecida desde la hoja Especies de la botánica)
-- Correr DESPUÉS de migration_catalogo.sql. ON CONFLICT (nombre_cientifico) DO NOTHING.

insert into catalogo.especies (
  nombre_cientifico, autor, genero, epiteto, familia, orden, nombres_comunes, descripcion, foto_url, usos, iucn, cites, origen, dispersion, polinizacion, rol_sucesional, tipo_semilla, tratamiento_pregerminativo, en_catalogo, en_ras, en_vivero, n_arboles_ras, slug
) values
  ('Aegiphila integrifolia', NULL, 'Aegiphila', 'integrifolia', NULL, NULL, array['Tabaquillo']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Agua 2 horas', false, false, true, 0, NULL),
  ('Albizia pedicellaris', NULL, 'Albizia', 'pedicellaris', 'FABACEAE', NULL, array['Sin registro']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, true, false, 1, NULL),
  ('Alibertia claviflora', 'K.Schum.', 'Alibertia', 'claviflora', 'RUBIACEAE', 'Gentianales', array['Borojo amazonico', 'Caimo', 'Borojo']::text[], 'Árbol de sotobosque. Fuste recto. Corteza externa marrón rojizo. Corteza interna amarilla, fibrosa. Hojas simples, opuestas, con estípulas triangulares. Flores tubulares blancas. Fruto globoso café.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/alibertia_claviflora.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 6, 'alibertia_claviflora'),
  ('Anacardium excelsum', '(Bertero & Balb. ex Kunth) Skeels', 'Anacardium', 'excelsum', 'ANACARDIACEAE', 'Sapindales', array['Caracoli']::text[], 'Árbol caducifolio, hojas simples, alternas, glabras, coriáceas. Flores con cinco pétalos verde pálido a blanco, tornando rosados en flores viejas . Fruto carnoso en forma de riñón.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/anacardium_excelsum.jpg', array['Alimento animal', 'alimento humano', 'medicamento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, 'No se realizó', true, true, true, 5, 'anacardium_excelsum'),
  ('Aniba guianensis', 'Aubl.', 'Aniba', 'guianensis', 'LAURACEAE', 'Laurales', array['"Canelo"', 'Canelo real']::text[], 'Árbol de dosel. Fuste recto. Pequeñas raíces tabulares, corteza externa fisurada, corteza interna amarilla, olor ranal de laurel. Hojas simples, alternas, blanquecinas en el envés, peciolos negros. Frutos en drupa elipsoide con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/aniba_guianensis.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'aniba_guianensis'),
  ('Apeiba macropetala', 'Ducke', 'Apeiba', 'macropetala', 'MALVACEAE', 'Malvales', array['Peinemono', 'Guanabano de montaña', 'Guamo colorado']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón oscuro que desprende en tiras largas. Corteza interna amarillenta con mucilago pegachento. Hojas simples, alternas, pubescentes, con envés blanco, tres venas saliendo de la base. Flores amarillas. Frutos con indehiscente, exocarpo con salientes en puntas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/apeiba_macropetala.jpg', array['Ambiental']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 12, 'apeiba_macropetala'),
  ('Apeiba membranacea', NULL, 'Apeiba', 'membranacea', NULL, NULL, array['Peine mono']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'ORTODOXA', 'agua 3 horas', false, false, true, 0, NULL),
  ('Aspidosperma excelsum', 'Benth.', 'Aspidosperma', 'excelsum', 'APOCYNACEAE', 'Gentianales', array['Costillo']::text[], 'Árbol de fuste fuertemente acanalado o fenestrado, corteza externa amarilla. Hojas ovadas a elípticas, simples, alternas, con envés blanquecino. Presenta látex de blanco a crema. Inflorescencias terminales, flor tubular verde. Frutos en capsula con apertura bilateral, semillas aladas color crema.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/aspidosperma_excelsum.jpg', array['Medicinal', 'Maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 25, 'aspidosperma_excelsum'),
  ('Astrocaryum chambira', 'Burret', 'Astrocaryum', 'chambira', 'ARECACEAE', 'Arecales', array['Chambira']::text[], 'Palma con espinas en el tallo, hojas erguidas con pinnas dispuestas de manera regular a lado y lado del raquis en varios planos, pinnas blanquecinas en el envés y con espinas cortas en el margen, peciolo con espinas. Inflorescencias con flores femeninas solo en la base. Frutos ovados a esféricos de color verde amarillento al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/astrocaryum_chambira.jpg', array['Alimento animal', 'medicinal', 'ambientales', 'sociales', 'combustible']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 2, 'astrocaryum_chambira'),
  ('Bixa orellana', NULL, 'Bixa', 'orellana', NULL, NULL, array['Achiote']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'ORTODOXA', 'No se realizó', false, false, true, 0, NULL),
  ('Brosimum lactescens', '(S.Moore) C.C.Berg', 'Brosimum', 'lactescens', 'MORACEAE', 'Rosales', array['Leche chiva']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón con lenticelas transversales. Corteza interna amarilla con látex blanco o crema. Hojas simples, alternas, glabras o pubescentes en la vena central. Estípula terminal pequeña. Frutos maduros color naranja o rojo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/brosimum_lactescens.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 3, 'brosimum_lactescens'),
  ('Brosimum parinarioides', 'Ducke', 'Brosimum', 'parinarioides', 'MORACEAE', 'Rosales', array['Pelacara blanco']::text[], 'Árbol de dosel. Fuste recto. Corteza externa rojiza con lenticelas. Corteza interna amarilla con abundante látex blanco. Hojas simples, alternas, con vernación terciaria reticulada. Estípula terminal de 3 a 5 cm. Frutos verdes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/brosimum_parinarioides.jpg', array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'brosimum_parinarioides'),
  ('Byrsonima krukoffii', 'W.R.Anderson', 'Byrsonima', 'krukoffii', 'MALPIGHIACEAE', 'Malpighiales', array['Hojiancho', 'Lloron']::text[], 'Árbol de sotobosque. Fuste recto. Corteza externa lenticelada amarillentaa. Corteza interna rosada. Hojas pubescentes buladas, ferruginosas. Flores amarillas. Frutos tomentosos o pilosos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/byrsonima_krukoffii.jpg', array['Ambiental']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Pionera', NULL, NULL, true, true, false, 4, 'byrsonima_krukoffii'),
  ('Calophyllum brasiliense', 'Cambess.', 'Calophyllum', 'brasiliense', 'CALOPHYLLACEAE', 'Malpighiales', array['Bálsamo rosado']::text[], 'Árbol de dosel emergente. Fuste recto, corteza muerta marrón, corteza viva amarillenta, arenosa, dura. Exudado amarillento escaso saliendo en puntos. Hojas simples, opuestas, glabras (lisas), de consistencia coriácea (como cuero). Flores incompletas, imperfectas con tépalos verde a blanco. Frutos globosos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/calophyllum_brasiliense.jpg', array['Alimento aminal', 'medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'calophyllum_brasiliense'),
  ('Capirona macrophylla', '(Poepp.) Delprete', 'Capirona', 'macrophylla', 'RUBIACEAE', 'Gentianales', array['Resbala monos', 'Capiron de montaña']::text[], 'Árbol de sotobosque. Fuste recto. Corteza muerta rojiza-verdosa, muy lisa, con amplias escamas rojizas y lenticelas transversales. Corteza viva externa verde, media e interna marrón blancuzcas que oxida marrón. Hojas simples, opuestas, con estípulas triangulares alargadas. Flores blancas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/capirona_macrophylla.jpg', array['Medicinal', 'alimento']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 3, 'capirona_macrophylla'),
  ('Caryocar glabrum', '(Aubl.) Pers.', 'Caryocar', 'glabrum', 'CARYOCARACEAE', 'Malpighiales', array['Mani', 'Maní', 'Quina']::text[], 'Árbol de fuste recto con aletones. corteza muerta marrón a negro, en placas que desprenden, lenticelada. Hojas compuestas, opuestas, trifolioladas. Flores con pétalos color crema a amarillo, estambres rosados. Fruto globoso café a marrón.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/caryocar_glabrum.jpg', array['Alimento humano', 'alimento animal', 'veneno', 'medicinal', 'combustible']::text[], 'LC', 'NA', 'Nativa', 'Barocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 8, 'caryocar_glabrum'),
  ('Caryodendron orinocense', NULL, 'Caryodendron', 'orinocense', NULL, NULL, array['Tacay/castaño']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'RECALCITRANTE', 'No se realizó', false, false, true, 0, NULL),
  ('Cassia fistula', 'L.', 'Cassia', 'fistula', 'FABACEAE', 'Fabales', array['Cañofistulo']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa lecticelada color marrón oscuro. Corteza viva amarillenta, olor amargo. Hojas compuestas, alternas, con estípulas. Flores amarillas, frutos alargados cilíndricos. Semillas color café.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/cassia_fistula.jpg', array['Alimento animal', 'alimento humano', 'veneno', 'medicinal', 'combustible']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 1, 'cassia_fistula'),
  ('Cassia grandis', 'L.f.', 'Cassia', 'grandis', 'FABACEAE', 'Fabales', array['Ahumado barbasco', 'Chocho amargo']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa lecticelada color marrón oscuro. Corteza viva amarillenta, olor amargo. Hojas compuestas, alternas, de foliolos opuestos. Con estípulas. Flores rosadas, frutos alargados cilíndricos. Semillas color café.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/cassia_grandis.jpg', array['Alimento', 'Medicina', 'Cultural']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 2, 'cassia_grandis'),
  ('Cedrela odorata', 'L.', 'Cedrela', 'odorata', 'MELIACEAE', 'Sapindales', array['Cedro rojo', '"Cedro rosado"', 'Cedro blanco']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón oscuro, fisurada longitudinalmente, formado placas que desprenden. Corteza interna rosada a roja. Hojas compuestas, alternas de numerosos foliolos opuestos asimétricos. Fruto en cápsula elipsoidal con 5 valvas de color negro con puntos claros. Semillas aladas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/cedrela_odorata.jpg', array['Medicinal', 'ambiental', 'alimento animal']::text[], 'VU', 'Apendice II', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', 'ORTODOXA', 'No se realizó', true, true, true, 11, 'cedrela_odorata'),
  ('Cedrelinga cateniformis', '(Ducke) Ducke', 'Cedrelinga', 'cateniformis', 'FABACEAE', 'Fabales', array['Achapo', 'Achapo blanco', 'Achapo colorao']::text[], 'Árbol de dosel emergente. Raíces con contrafuertes. Fuste recto. Corteza muerta fisurada color marrón rojizo. Exudado acuoso rojo. Corteza viva amarillenta. Hojas doblemente compuestas, alternas, de foliolos opuestos, con glándulas en el raquis. Frutos aplanados, septados.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/cedrelinga_cateniformis.jpg', array['Ambientales', 'medicinal', 'combustible', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila (Entomófila)', 'Tardia', 'RECALCITRANTE', 'dejar al sol 1 día', true, true, true, 31, 'cedrelinga_cateniformis'),
  ('Ceiba pentandra', '(L.) Gaertn.', 'Ceiba', 'pentandra', 'MALVACEAE', 'Malvales', array['Ceiba', 'Carrecillo', 'Ceiba bonga']::text[], 'Árbol de dosel emergente. Fuste recto abombado con o sin espinas, estriado o fisurado longitudinalmente. Corteza interna amarilla muy dura con olor amargo. Hojas palmeadocompuestas con 5-7 foliolos. Flores color crema. Frutos en cápsulas elipsoidales o piriformes con semillas negras.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ceiba_pentandra.jpg', array['Alimento animal', 'veneno', 'medicinal', 'combustible']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 4, 'ceiba_pentandra'),
  ('Cespedesia spathulata', '(Ruiz & Pav.) Planch.', 'Cespedesia', 'spathulata', 'OCHNACEAE', 'Malpighiales', array['Clavija']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón a amarillo, lenticelado. Con númerosas estípulas ocres. Hojas simples alternas, agrupadas hacia el final de las ramas. flores amarillas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/cespedesia_spathulata.jpg', array['Medicina', 'Combustible', 'Ambientales']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 2, 'cespedesia_spathulata'),
  ('Clarisia racemosa', 'Ruiz & Pav.', 'Clarisia', 'racemosa', 'MORACEAE', 'Rosales', array['Pelacara', 'Granadillo']::text[], 'Árbol de dosel emergente. Fuste recto con aletones. Corteza externa roja con lenticelas en anillos transversales. Corteza viva amarillenta, con abundante látex blanco. Hojas simples, alternas, glabras y coriáceas. Estípula terminal pequeña. Frutos rojos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/clarisia_racemosa.jpg', array['Alimento animal', 'medicinal', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', 'no encontré en literatura', 'Agua durante 12 horas', true, true, true, 12, 'clarisia_racemosa'),
  ('Cordia alliodora', '(Ruiz & Pav.) Oken', 'Cordia', 'alliodora', 'BORAGINACEAE', 'Boraginales', array['Nogal caqueteño', 'Nogal Caqueteño']::text[], 'Árbol de dosel emergente, caducifolio. Fuste recto, corteza muerta marrón a negro que desprende en tiras largas, corteza viva amarilla. Ramas con crecimiento en sombrilla y presencia de domacios. Flores blancas. Fruto elipsoide de paredes delgadas y fibrosas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/cordia_alliodora.jpg', array['Alimento animal', 'medicinal', 'ambientales', 'sociales']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', 'ORTODOXA', 'No se realizó', true, true, true, 13, 'cordia_alliodora'),
  ('Couma macrocarpa', 'Barb.Rodr.', 'Couma', 'macrocarpa', 'APOCYNACEAE', 'Gentianales', array['Juansoco', 'Juansoco, perillo']::text[], 'Árbol emergente de fuste recto, corteza muerta marrón rojizo. Corteza viva con látex blanco de sabor dulce. Hojas opuestas en verticilos de tres. Frutos globosos que maduran de color amarillento. Numerosas semillas de 1 cm de largo, embebidas en una pulpa dulce, de consistencia fibrosa-chiclosa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/couma_macrocarpa.jpg', array['Medicina', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 28, 'couma_macrocarpa'),
  ('Couratari guianensis', 'Aubl.', 'Couratari', 'guianensis', 'LECYTHIDACEAE', 'Ericales', array['Abarco caqueteño, Carguero', 'Fono cabuyo']::text[], 'Árbol de dosel emergente. Fuste recto. Raíces tabulares. Corteza externa marrón oscuro. Corteza interna color café. Hojas simples, alternas, nerviación acródroma, envés discolor. flores de pétalos blancos con visos rosados, en panículas terminales. Frutos en pixidios cilíndricos con semillas aladas alargadas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/couratari_guianensis.jpg', array['Alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 7, 'couratari_guianensis'),
  ('Couroupita guianensis', NULL, 'Couroupita', 'guianensis', NULL, NULL, array['Bala de cañón']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'RECALCITRANTE', 'Agua 1 hora', false, false, true, 0, NULL),
  ('Croton matourensis', 'Aubl.', 'Croton', 'matourensis', 'EUPHORBIACEAE', 'Malpighiales', array['Papelillo, palo blanco', 'Papelillo']::text[], 'Árbol de sotobosque. Fuste recto de apariencia amarillenta. Corteza viva rosada con betas rojas. Hojas simples, alternas, con envés blancuzco a ferrugíneo brillante. Glándulas nectaríferas pareadas en la base de la hoja por el envés. Flores unisexuales.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/croton_matourensis.jpg', array['Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Pionera', NULL, NULL, true, true, false, 13, 'croton_matourensis'),
  ('Dacryodes chimantensis', 'Steyerm. & Maguire', 'Dacryodes', 'chimantensis', 'BURSERACEAE', 'Sapindales', array['Algodoncillo', 'Caraño']::text[], 'Árbol de dosel emergente. Fuste recto, corteza muerta color negro, corteza viva color amarillo, exudado saliendo en puntos color crema. Hojas compuestas imparipinnadas, opuestas de foliolos opuestos. Frutos amarillos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/dacryodes_chimantensis.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'dacryodes_chimantensis'),
  ('Dialium guianense', '(Aubl.) Sandwith', 'Dialium', 'guianense', 'FABACEAE', 'Fabales', array['Guayacan rosado', 'Poblano o avillo']::text[], 'Árbol de dosel alto. Fuste recto. corteza muerta marrón con placas y lenticelas. Corteza viva rojiza con betas moradas, ocasionalmente con exudado rojo acuoso. Olor dulce. Hojas compuestas, alternas, foliolos alternos. Flores amarillento verdoso. Frutos indehiscentes elipsoidales.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/dialium_guianense.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'dialium_guianense'),
  ('Didymopanax morototoni', '(Aubl.) Decne. & Planch.', 'Didymopanax', 'morototoni', 'ARALIACEAE', 'Apiales', array['Mano de oso', 'Mano de Oso', 'Sin registro']::text[], 'Árbol de dosel, fuste recto, corteza externa amarillenta. Corteza viva naranja con vetas blancas, que oxida color ocre. Hojas palmeado compuestas con envés ferrugíneo. Frutos bilobulados y comprimidos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/didymopanax_morototoni.jpg', array['Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Pionera', NULL, 'No se realizó', true, true, true, 9, 'didymopanax_morototoni'),
  ('Dipteryx micrantha', 'Harms', 'Dipteryx', 'micrantha', 'FABACEAE', 'Fabales', array['Serrapio']::text[], 'Árbol de dosel emergente. Raíces con contrafuertes. Fuste recto. Corteza desprende en placas redondas. Hojas imparipinnadas gruesas color verde oscuro, peciolulos negros. Plántulas con raquis alado. Fruto liso de verde a amarillo al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/dipteryx_micrantha.jpg', array['Medicinal', 'alimento']::text[], 'DD', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'dipteryx_micrantha'),
  ('Duguetia quitarensis', 'Benth.', 'Duguetia', 'quitarensis', 'ANNONACEAE', 'Magnoliales', array['Nagüi']::text[], 'Árbol de fuste recto, corteza muerta marrón claro, estriada, corteza viva amarillenta. Hojas elípticas con escamas de color blanco en el envés y en las ramas jóvenes. Flores laterales solitarias. Fruto globoso con pulpa blanquecina comestible, semilla ovoide aplanada de color rojizo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/duguetia_quitarensis.jpg', array['Medicina', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 3, 'duguetia_quitarensis'),
  ('Endlicheria macrophylla', '(Meisn.) Mez', 'Endlicheria', 'macrophylla', 'LAURACEAE', 'Laurales', array['Amarillo real']::text[], 'Árbol de dosel. Fuste recto. Corteza externa lenticelada color amarillo. Corteza interna amarilla, aromático. Hojas simples, alternas, agrupadas al final de las ramas, envés pubescente. Frutos en drupa elipsoide con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/endlicheria_macrophylla.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'endlicheria_macrophylla'),
  ('Endlicheria metallica', 'Kosterm.', 'Endlicheria', 'metallica', 'LAURACEAE', 'Laurales', array['Laurel amarillo', 'Laurel', 'Amarillo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa lenticelada color amarillo. Corteza interna amarilla, aromático. Hojas simples, alternas, envés blanquecino o ferroso. Frutos en drupa elipsoide con cúpula roja.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/endlicheria_metallica.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 5, 'endlicheria_metallica'),
  ('Endlicheria sericea', 'Nees', 'Endlicheria', 'sericea', 'LAURACEAE', 'Laurales', array['Amarillo medio comino', 'Amarillo real', 'Comino real']::text[], 'Árbol de dosel. Fuste recto con bambas o aletones altos. Corteza externa lenticelada color amarillo. Corteza interna amarilla, aromático a canela. Hojas simples, alternas, envés amarillento a blancuzco. Frutos en drupa elipsoide con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/endlicheria_sericea.jpg', array['Medicinal', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 5, 'endlicheria_sericea'),
  ('Enterolobium schomburgkii', NULL, 'Enterolobium', 'schomburgkii', NULL, NULL, array['Orejero']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'ORTODOXA', 'Agua durante 5 horas', false, false, true, 0, NULL),
  ('Erisma uncinatum', 'Warm.', 'Erisma', 'uncinatum', 'VOCHYSIACEAE', 'Myrtales', array['Flor morado']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón claro, lenticelada. Corteza interna amarilla. Hojas simples, opuestas, vena media amarilla. Flores moradas a azules. Fruto en sámara.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/erisma_uncinatum.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 8, 'erisma_uncinatum'),
  ('Eschweilera bracteosa', '(Poepp. ex O.Berg) Miers', 'Eschweilera', 'bracteosa', 'LECYTHIDACEAE', 'Ericales', array['Fono negro', 'Fono colorado', 'Fono rojo']::text[], 'Fono negro Árbol de dosel. Fuste recto. Corteza externa marrón oscuro. Corteza interna rosada. Hojas simples, alternas, nerviación broquidodroma, peciolo acanalado, reflexo. Flores blancas con matices rosados. Frutos leñoso en forma de copa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/eschweilera_bracteosa.jpg', array['Ambiental', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 9, 'eschweilera_bracteosa'),
  ('Eschweilera coriacea', '(DC.) S.A.Mori', 'Eschweilera', 'coriacea', 'LECYTHIDACEAE', 'Ericales', array['Fono negro', 'Fono', 'Fono colorado']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón oscuro lenticelada. Corteza viva blanda color amarillo claro. Hojas simples, alternas, nerviación broquidrodroma, peciolo acanalado, recurvado o feflexo. Frutos leñoso en forma de copa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/eschweilera_coriacea.jpg', array['Medicinal', 'alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 10, 'eschweilera_coriacea'),
  ('Eschweilera gigantea', '(R.Knuth) J.F.Macbr.', 'Eschweilera', 'gigantea', 'LECYTHIDACEAE', 'Ericales', array['Fono colorado']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón oscuro fisurada longitudinalmente. Corteza viva blanda color amarillo. Hojas simples, alternas, nerviación broquidrodroma, peciolo acanalado, recurvado. Frutos leñoso en forma de copa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/eschweilera_gigantea.jpg', array['Ambiental', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'eschweilera_gigantea'),
  ('Ficus nymphaeifolia', 'Mill.', 'Ficus', 'nymphaeifolia', 'MORACEAE', 'Rosales', array['Higueron', 'Madroño']::text[], 'Árbol de dosel emergente. Fuste recto con aletones. Corteza externa marrón rojizo. Corteza interna amarilla con látex blanco saliendo en puntos. Hojas simples, alternas, con envés glauco (blanquecino), base cordada. Estípula terminal cónica de tamaño medio. Frutos verdes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ficus_nymphaeifolia.jpg', array['Medicinal', 'sociales']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 2, 'ficus_nymphaeifolia'),
  ('Garcinia apostoloi', 'Mouzinho', 'Garcinia', 'apostoloi', 'CLUSIACEAE', 'Malpighiales', array['Manguillo', 'Sajo o azufre']::text[], 'Árbol de dosel emergente. Corteza externa marrón. Látex amarillo saliendo en puntos, olor dulce. Hojas simples opuestas. Flor con pétalos rosados. Fruto de corteza amarilla.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/garcinia_apostoloi.jpg', array['Alimento animal', 'amimento humano', 'ambiental']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 11, 'garcinia_apostoloi'),
  ('Garcinia brasiliensis', 'Mart.', 'Garcinia', 'brasiliensis', 'CLUSIACEAE', 'Malpighiales', array['Madroño', 'Madroño amazonico']::text[], 'Árbol de dosel con fuste recto. Corteza muerta marrón oscuro, fisurada. Corteza viva amarillenta, con látex amarillo. Hojas simples, opuestas, coriáceas, oblongas. Frutos de cubierta gruesa, lisa, amarilla.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/garcinia_brasiliensis.jpg', array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 4, 'garcinia_brasiliensis'),
  ('Garcinia macrophylla', 'Mart.', 'Garcinia', 'macrophylla', 'CLUSIACEAE', 'Malpighiales', array['Madroño']::text[], 'Árbol de dosel con fuste recto. corteza muerta marrón oscuro, fisurada. Corteza viva amarillenta, con látex amarillo. Hojas simples, opuestas, coriáceas, oblongas. Flores solitarias o en fascículos laterales, con cuatro pétalos blancos. Frutos de cubierta gruesa, lisa, amarilla.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/garcinia_macrophylla.jpg', array['Alimento animal', 'amimento humano', 'medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'garcinia_macrophylla'),
  ('Garcinia madruno', NULL, 'Garcinia', 'madruno', 'CLUSIACEAE', NULL, array['Madroño']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, true, false, 1, NULL),
  ('Geissanthus occidentalis', 'Cuatrec.', 'Geissanthus', 'occidentalis', 'PRIMULACEAE', 'Ericales', array['Gomo rosado']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón grisáceo, fisurada. Corteza interna dura arenosa, con olor dulce. Hojas simples, alternas, agrupadas al final de las ramas, venas secundarias paralelas poco notorias. Frutos globosos de rojo a morado o negro al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/geissanthus_occidentalis.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 1, 'geissanthus_occidentalis'),
  ('Guarea guidonia', '(L.) Sleumer', 'Guarea', 'guidonia', 'MELIACEAE', 'Sapindales', array['Bilibil', 'Fono blanco']::text[], 'Árbol de dosel, Fuste recto con bambas. Corteza externa marrón oscuro, fisurada. Corteza interna amarilla. Hojas compuestas, alternas, de foliolos grandes paripinnados. Frutos globulares de color café a rojo al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/guarea_guidonia.jpg', array['Alimento animal', 'medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', 'RECALCITRANTE', 'No se realizó', true, true, true, 4, 'guarea_guidonia'),
  ('Guarea silvatica', 'C.DC.', 'Guarea', 'silvatica', 'MELIACEAE', 'Sapindales', array['Bilibili']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza interna amarilla, madera fibrosa. Aromático dulce suave. Hojas compuestas, alternas. Frutos triloculares rojizo grande con tres semillas', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/guarea_silvatica.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 2, 'guarea_silvatica'),
  ('Handroanthus obscurus', '(Bureau & K.Schum.) Mattos', 'Handroanthus', 'obscurus', 'BIGNONIACEAE', 'Lamiales', array['Guayacan']::text[], 'Árbol de sotobosque o dosel bajo. Hojas palmeado compuestas, opuestas, glabras (sin indumento), peciolos, peciolulos y vena central color marrón. Flores tubulares amarillas. Frutos en cápsula lineal con apertura bilateral y pubescencia persistente .', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/handroanthus_obscurus.jpg', array['Medicinal', 'ambiental', 'ornamental']::text[], 'LC', 'Apendice II', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 1, 'handroanthus_obscurus'),
  ('Helicostylis scabra', '(J.F.Macbr.) C.C.Berg', 'Helicostylis', 'scabra', 'MORACEAE', 'Rosales', array['Leche chivo']::text[], NULL, NULL, array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 3, NULL),
  ('Helicostylis tomentosa', '(Poepp. & Endl.) Rusby', 'Helicostylis', 'tomentosa', 'MORACEAE', 'Rosales', array['Granadillo', 'Leche chiva']::text[], 'Leche chiva Árbol del dosel. Fuste recto. Corteza externa grisácea, con estrías, lenticelas y escamas. Corteza viva amarillenta, con látex crema. Hojas simples, alternas con envés tomentoso ligeramente áspero. Flores con sexos separados. Fruto compuesto, globoso, achatado de color amarillo al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/helicostylis_tomentosa.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'helicostylis_tomentosa'),
  ('Hevea brasiliensis', NULL, 'Hevea', 'brasiliensis', NULL, NULL, array['Caucho']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'RECALCITRANTE', 'Agua 1 hora', false, false, true, 0, NULL),
  ('Hevea guianensis', 'Aubl.', 'Hevea', 'guianensis', 'EUPHORBIACEAE', 'Malpighiales', array['Caucho']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón oscuro. Corteza viva con abundante látex blanco. Hojas trifolioladas, alternas, discoloras, ápice acuminado. Fruto con dehiscencia explosiva.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/hevea_guianensis.jpg', array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 1, 'hevea_guianensis'),
  ('Hevea nitida', 'Mart. ex Müll.Arg.', 'Hevea', 'nitida', 'EUPHORBIACEAE', 'Malpighiales', array['Siringa nativa', 'Siringo', 'Guarango']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón oscuro. Corteza viva con abundante látex blanco saliendo en puntos. Hojas compuestas, alternas, trifolioladas, discoloras. Fruto con dehiscencia explosiva.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/hevea_nitida.jpg', array['Alimento', 'recinas', 'material']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 6, 'hevea_nitida'),
  ('Hevea pauciflora', '(Spruce ex Benth.) Müll.Arg.', 'Hevea', 'pauciflora', 'EUPHORBIACEAE', 'Malpighiales', array['Siringa nativa', 'Siringo']::text[], 'Siringa nativa Árbol de dosel emergente. Fuste recto. Corteza externa marrón oscuro. Corteza viva con abundante látex blanco. Hojas compuestas, alternas, trifolioladas, discoloras, ápice acuminado. Fruto con dehiscencia explosiva.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/hevea_pauciflora.jpg', array['Alimento', 'recinas', 'material']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 4, 'hevea_pauciflora'),
  ('Hieronyma alchorneoides', 'Allemão', 'Hieronyma', 'alchorneoides', 'PHYLLANTHACEAE', 'Malpighiales', array['Arenillo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón grisáceo, fisurada. Corteza interna blanda, amarilla. Hojas simples, alternas, peciolos rojos, pulvínulo engrosado en la inserción a la hoja, estípulas foliosas abombadas. Frutos globosos o elipsoides color morado a negro al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/hieronyma_alchorneoides.jpg', array['Medicinal', 'alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Pionera', NULL, NULL, true, true, false, 1, 'hieronyma_alchorneoides'),
  ('Hymenaea oblongifolia', 'Huber', 'Hymenaea', 'oblongifolia', 'FABACEAE', 'Fabales', array['Tamarindo', 'Algarrobo', 'Algarrobo, tamarindo']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón rojiza, estriada. Corteza viva amarilla con betas rojizas. Hojas bifolioladas oblongoelípticas, alternas. Estípulas caedizas. Frutos indehiscentes elipsoidales comprimidos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/hymenaea_oblongifolia.jpg', array['Alimento animal', 'medicinal', 'ambiental', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 11, 'hymenaea_oblongifolia'),
  ('Inga alba', '(Sw.) Willd.', 'Inga', 'alba', 'FABACEAE', 'Fabales', array['Guamo colorado', 'Guamo colorao']::text[], 'Árbol de dosel alto, con fuste recto. Corteza con apariencia blancuzca a amarilla. Corteza interna rosada. Hojas compuestas, alternas, con entre 6 a 8 foliolos opuestos. Con glándulas nectaríferas en el raquis. Flores blancas muy aromáticas dulce. Fruto largo comprimido con entre 10 a 15 semillas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/inga_alba.jpg', array['Medicinal', 'ambiental', 'alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 3, 'inga_alba'),
  ('Inga capitata', 'Desv.', 'Inga', 'capitata', 'FABACEAE', 'Fabales', array['Guamo colorado', 'Guamo colorao', 'Guamo cerindo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa muy lenticelada de apariencia amarilla grisácea. Corteza interna rosada. Hojas compuestas, alternas, de cuatro foliolos opuestos. Glándulas en el raquis. Flores blancas muy aromáticas a dulce. Frutos alargados comprimidos.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/inga_capitata.jpg', array['Alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 7, 'inga_capitata'),
  ('Inga cylindrica', '(Vell.) Mart.', 'Inga', 'cylindrica', 'FABACEAE', 'Fabales', array['Guamo colorado', 'Guamo colorao']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón oscuro, lenticelada. Corteza interna rosada a amarilla, olor dulce. Hojas compuestas, alternas, numerosos foliolos opuestos inequilateros, glándulas en el raquis. Flores blancas muy aromáticas. Fruto alargado rollizo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/inga_cylindrica.jpg', array['Alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 4, 'inga_cylindrica'),
  ('Inga edulis', NULL, 'Inga', 'edulis', NULL, NULL, array['Guama rabo de mico']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'RECALCITRANTE', 'No se realizó', false, false, true, 0, NULL),
  ('Inga tessmannii', 'Harms', 'Inga', 'tessmannii', 'FABACEAE', 'Fabales', array['Caimo rojo']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta color marrón rojizo que desprende en placas cuadradas. Hojas compuestas, alternas, de foliolos grandes, equiláteros, sin raquis alado, glándulas sobre el raquis. Fruto largo aplanado.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/inga_tessmannii.jpg', array['Alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 1, 'inga_tessmannii'),
  ('Inga thibaudiana', 'DC.', 'Inga', 'thibaudiana', 'FABACEAE', 'Fabales', array['Caimitillo', 'Guamo colorao']::text[], 'Árbol de dosel con fuste recto. Corteza muerta marrón amarillenta, con lenticelas transversales. Corteza viva rojiza a amarillenta; envés de los folíolos, pecíolo, ramillas jóvenes y frutos con superficie pubescente ferrugínea. Frutos aplanados.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/inga_thibaudiana.jpg', array['Alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 2, 'inga_thibaudiana'),
  ('Iryanthera hostmannii', '(Benth.) Warb.', 'Iryanthera', 'hostmannii', 'MYRISTICACEAE', 'Magnoliales', array['Sangre toro', 'Sangretoro rojo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón rojiza. Corteza interna rosada, exudado rojo acuoso. Hojas simples, alternas. Frutos caulinares, exocarpo verde, semilla con arilo rojo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/iryanthera_hostmannii.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 3, 'iryanthera_hostmannii'),
  ('Jacaranda copaia', '(Aubl.) D.Don', 'Jacaranda', 'copaia', 'BIGNONIACEAE', 'Lamiales', array['Pavito', 'Maduraplatano', 'Canalete']::text[], 'Árbol de dosel emergente, fuste recto, amarillento, fisurado. Corteza interna fibrosa dura con betas amarillas y marrones. Hojas doblemente compuestas, opuestas. Flores tubulares moradas. Frutos con apertura bilateral, semillas aladas color crema.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/jacaranda_copaia.jpg', array['Medicinal', 'combustible', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, 'No se realizó', true, true, true, 12, 'jacaranda_copaia'),
  ('Leptobalanus apetalus', '(E.Mey.) Sothers & Prance', 'Leptobalanus', 'apetalus', 'CHRYSOBALANACEAE', 'Malpighiales', array['Nn', 'Polvillo decacho']::text[], 'Árbol de fuste. Corteza muerta marrón a negro, corteza viva arenosa color café. Hojas simples, alternas. Fruto globoso color verde a café o marrón al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/leptobalanus_apetalus.jpg', array['Alimento', 'Medicina']::text[], 'NE', 'NA', 'Nativa', 'Barocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 2, 'leptobalanus_apetalus'),
  ('Manilkara bidentata', '(A.DC.) A.Chev.', 'Manilkara', 'bidentata', 'SAPOTACEAE', 'Ericales', array['Balato real', 'Balato', 'Leche chiva']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón grisáceo. Corteza interna marrón amarillento, látex blanco a crema saliendo en puntos. Hojas simples, alternas, con margen revoluto, venas secundarias paralelas, envés discoloro a ferrugíneo. Flores blancas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/manilkara_bidentata.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 7, 'manilkara_bidentata'),
  ('Maquira calophylla', NULL, 'Maquira', 'calophylla', 'MORACEAE', 'Rosales', array['Leche chivo']::text[], 'Árbol del dosel. Fuste recto. Corteza externa marron. Corteza viva amarilla, con látex color crema o café con leche. Hojas simples, alternas, glabras, venas terciarias reticuladas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/maquira_calophylla.jpg', array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'maquira_calophylla'),
  ('Matisia cordata', NULL, 'Matisia', 'cordata', NULL, NULL, array['sapote']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'RECALCITRANTE', 'No se realizó', false, false, true, 0, NULL),
  ('Matisia ochrocalyx', 'K.Schum.', 'Matisia', 'ochrocalyx', 'MALVACEAE', 'Malvales', array['Sapote de monte']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza interna amarilla. Hojas simples, alternas, con tres venas saliendo de la base, peciolos con doble pulvínulo. Flores blancas, frutos verdes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/matisia_ochrocalyx.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'matisia_ochrocalyx'),
  ('Micropholis venulosa', '(Mart. & Eichler) Pierre', 'Micropholis', 'venulosa', 'SAPOTACEAE', 'Ericales', array['Caimo piedro']::text[], 'Caimo piedro Árbol de dosel emergente. Fuste recto. Corteza externa marrón grisáceo, con desprendimiento en placas, fisurada. Corteza interna marrón amarillento, látex blanco saliendo en puntos. Hojas simples, alteras, ápice caudado, envés discoloro a ferrugíneo. Fruto marrón.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/micropholis_venulosa.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'micropholis_venulosa'),
  ('Minquartia guianensis', 'Aubl.', 'Minquartia', 'guianensis', 'OLACACEAE', 'Santalales', array['Barbasco', 'Ahumado real', 'Ahumado negro']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón que desprende en placas. Corteza interna color café amarillento, con exudado escaso pegachento. Hojas simples, alternas con envés ferrugíneo. Frutos de verde a rojo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/minquartia_guianensis.jpg', array['Maderable', 'medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, 'No se realizó', true, true, true, 37, 'minquartia_guianensis'),
  ('Myrcia splendens', '(Sw.) DC.', 'Myrcia', 'splendens', 'MYRTACEAE', 'Myrtales', array['Gomo cucharo']::text[], 'Árbol de sotobosque. Fuste recto. Corteza externa amarilla papelosa, corteza interna rosada. Hojas simples, opuestas, con puntos translucidos y olor a guayaba verde. Flores blancas. Frutos de verde – rojo – morado al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/myrcia_splendens.jpg', array['Medicinal', 'alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', NULL, NULL, NULL, NULL, NULL, true, true, false, 1, 'myrcia_splendens'),
  ('Nectandra hihua', '(Ruiz & Pav.) Rohwer', 'Nectandra', 'hihua', 'LAURACEAE', 'Laurales', array['Laurel mierda']::text[], 'Árbol de dosel. Fuste recto. Corteza externa e interna color amarillo. Aromático fuerte a laurel. Hojas simples, alternas. Inflorescencia con pedúnculos rojizos. Flores blancas. Frutos en drupa elipsoide con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/nectandra_hihua.jpg', array['Maderable', 'Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'nectandra_hihua'),
  ('Ochroma pyramidale', '(Cav. ex Lam.) Urb.', 'Ochroma', 'pyramidale', 'MALVACEAE', 'Malvales', array['Balso', 'Balso colorado']::text[], 'Árbol de crecimiento rápido. Fuste recto. Corteza externa marrón clara, escamosa. Corteza interna fibrosa amarillenta. Hojas simples, alternas, tomentosas, de base cordada. Flores blancas en forma de campana. Fruto capsular elipsoide a oblongo acanalado longitudinalmente, dehiscente por valvas lineales.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ochroma_pyramidale.jpg', array['Medicinal', 'alimento animal']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Pionera', 'ORTODOXA', 'Lijada, pringada agua caliente', true, true, true, 18, 'ochroma_pyramidale'),
  ('Ocotea aciphylla', '(Nees & Mart.) Mez', 'Ocotea', 'aciphylla', 'LAURACEAE', 'Laurales', array['Comino real', 'Amarillo mediocomino']::text[], 'Árbol de dosel. Fuste recto. Corteza externa amarillenta muy lenticelada. Corteza interna marrón rojiza. Olor muy fuerte a canela. Hojas simples, alternas, con venas amarillas, envés discoloro. Fruto en drupa verde a amarillo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_aciphylla.jpg', array['Medicinal', 'alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 28, 'ocotea_aciphylla'),
  ('Ocotea aurantiodora', '(Ruiz & Pav.) Mez', 'Ocotea', 'aurantiodora', 'LAURACEAE', 'Laurales', array['Laurel', 'Laurel negro', 'Amarillo blanco']::text[], 'Árbol de dosel. Fuste recto. Corteza con lenticelas longitudinales. Corteza interna amarilla, olor ranal fuerte. Hojas obovadas a elípticas, simples, alternas, discoloras, con venas amarillas. Frutos en drupas verdes a rojas al madurar con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_aurantiodora.jpg', array['Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 4, 'ocotea_aurantiodora'),
  ('Ocotea bofo', 'Kunth', 'Ocotea', 'bofo', 'LAURACEAE', 'Laurales', array['Laurel escobo o Laurel baboso']::text[], 'Árbol de dosel. Fuste recto. Corteza con lenticelas. Corteza interna amarilla, olor ranal fuerte. Hojas obovadas a elípticas, simples, alternas, con venas amarillas. Flores color crema. Frutos en drupa con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_bofo.jpg', array['Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'ocotea_bofo'),
  ('Ocotea cernua', '(Nees) Mez', 'Ocotea', 'cernua', 'LAURACEAE', 'Laurales', array['Canelo macho', 'Laurel indio viejo']::text[], 'Árbol de dosel. Fuste recto. Corteza interna amarilla, olor dulce suave. Hojas simples, alternas, con tres venas saliendo de la base, venas amarillas. Flores amarillas. Frutos en drupa con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_cernua.jpg', array['Medicinal', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'ocotea_cernua'),
  ('Ocotea floribunda', '(Sw.) Mez', 'Ocotea', 'floribunda', 'LAURACEAE', 'Laurales', array['Amarillo real']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón, leticelada. Olor ranal fuerte algo desagradable. Tallos jóvenes cuadrangurales. Hojas simples,, alternas, con veas amarillas. Flores axilares. Frutos globosos o elipsoidales.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_floribunda.jpg', array['Alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'ocotea_floribunda'),
  ('Ocotea gracilis', '(Meisn.) Mez', 'Ocotea', 'gracilis', 'LAURACEAE', 'Laurales', array['Laurel peña']::text[], 'Árbol de dosel. Fuste recto. Corteza externa leticelada. Corteza interna amarilla. Olor ranal fuerte suave. Hojas simples, alternas, con veas amarillas. Flores axilares. Frutos elipsoidales que maduran morado.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_gracilis.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 5, 'ocotea_gracilis'),
  ('Ocotea myriantha', '(Meisn.) Mez', 'Ocotea', 'myriantha', 'LAURACEAE', 'Laurales', array['Laurel anisoso']::text[], 'Árbol de dosel. Fuste recto. Corteza externa color negro leticelada. Corteza interna amarilla. Olor ranal. Hojas simples, alternas, con veas amarillas. Flores axilares color crema a verde. Frutos en drupa con cúpula.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_myriantha.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'ocotea_myriantha'),
  ('Ocotea oblonga', '(Meisn.) Mez', 'Ocotea', 'oblonga', 'LAURACEAE', 'Laurales', array['Indio viejo']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón amarillenta, lenticelada, agrietada. Corteza viva marrón amarillenta. Olor ranal fuerte. Hojas obovadas a elípticas con borde revoluto, discoloras, venas amarillas. Inflorescencias axilares. Frutos elipsoidales de color negruzco al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_oblonga.jpg', array['Alimento', 'medicinal', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', 'RECALCITRANTE', 'Agua 2 horas', true, true, true, 1, 'ocotea_oblonga'),
  ('Ocotea velloziana', '(Meisn.) Mez', 'Ocotea', 'velloziana', 'LAURACEAE', 'Laurales', array['Amarillo pelusa']::text[], 'Árbol de dosel. Fuste recto con bambas. Corteza externa lenticelada. Corteza interna amarilla. Poco olor ranal en tallo, más fuerte en hojas. Hojas simples, alternas, pubescentes en el envés y algo ferrugíneas en particular las hojas viejas. Fruto en drupa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ocotea_velloziana.jpg', array['Ambiental', 'maderable']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'ocotea_velloziana'),
  ('Oenocarpus bataua', 'Mart.', 'Oenocarpus', 'bataua', 'ARECACEAE', 'Arecales', array['Mil pesos']::text[], 'Palma de tallo liso con nodos notorios, hojas erguidas con pinnas dispuestas de manera regular a ambos lados del raquis en un solo plano de simetría. Pinnas blanquecinas en el envés. Inflorescencias colgantes. Frutos ovoide, elíptico u oblongo de color negro al madurar. Plántula con primeras hojas bífidas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/oenocarpus_bataua.jpg', array['Alimento animal', 'alimento humano', 'medicinal', 'ambientales', 'sociales', 'combustible']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'oenocarpus_bataua'),
  ('Ormosia santaremnensis', 'Ducke', 'Ormosia', 'santaremnensis', 'FABACEAE', 'Fabales', array['Chocho', 'Flor morado']::text[], 'Árbol de dosel emergente, Fuste recto. Raíces tabulares. Corteza externa amarilla lenticelada. Hojas ferrugíneas imparipinnadas de numerosos foliolos opuestos de ápice acuminado, venas impresas en el envés. Generalmente dos semillas por fruto, color rojo o rojo y negro.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/ormosia_santaremnensis.jpg', array['Ambiental', 'artesanal']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila (Entomófila)', 'Tardia', 'ORTODOXA', 'Agua 1 hora', true, true, true, 2, 'ormosia_santaremnensis'),
  ('Osteophloeum platyspermum', '(Spruce ex A.DC.) Warb.', 'Osteophloeum', 'platyspermum', 'MYRISTICACEAE', 'Magnoliales', array['Arracacho', 'Caimo colorado']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza muera color marrón, desprende en placas. Corteza viva amarillenta, con exudado hialino que oxida y se corta. Hojas simples, alternas, obovadas, con envés discoloro. Inflorescencias axilares.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/osteophloeum_platyspermum.jpg', array['Alimento animal', 'medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 10, 'osteophloeum_platyspermum'),
  ('Oxandra euneura', 'Diels', 'Oxandra', 'euneura', 'ANNONACEAE', 'Malpighiales', array['Cuerinegro nudoso']::text[], 'Árbol de dosel bajo del sotobosque. Fuste recto, corteza viva amarillenta, corteza externa negra que desprende en tiras largas. Hojas elípticas, simples, alternas, dísticas (dispuestas en un solo plano de simetría). Flores blancas, frutos de verdes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/oxandra_euneura.jpg', array['Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'oxandra_euneura'),
  ('Oxandra xylopioides', 'Diels', 'Oxandra', 'xylopioides', 'ANNONACEAE', 'Magnoliales', array['Golondrino']::text[], 'Árbol de dosel bajo del sotobosque. Fuste recto, corteza viva amarillenta, corteza externa desprende en tiras largas. Hojas elípticas, simples, alternas, dísticas (dispuestas en un solo plano de simetría). Frutos de verde a rojo al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/oxandra_xylopioides.jpg', array['Medicina', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'oxandra_xylopioides'),
  ('Parkia multijuga', 'Benth.', 'Parkia', 'multijuga', 'FABACEAE', 'Fabales', array['Guarango', 'Guarango Rosado', 'Guarango mulato']::text[], 'Árbol de dosel emergente. Raíces tabulares. Fuste recto. Corteza externa muy lenticelada en anillos. Corteza interna amarilla. Hojas compuestas, alternas bipinnadas. Flores amarillas. Fruto negro, aplanado y curvado.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/parkia_multijuga.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 4, 'parkia_multijuga'),
  ('Parkia nitida', 'Miq.', 'Parkia', 'nitida', 'FABACEAE', 'Fabales', array['Guarango rosado']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza muerta marrón amarillenta, muy lenticelada. Corteza viva marrón rojiza. Hojas compuestas, alternas o subopuestas, bipinnadas. Fruto negro, no dehiscente, alargado y aplanado.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/parkia_nitida.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'parkia_nitida'),
  ('Parkia pendula', '(Willd.) Benth. ex Walp.', 'Parkia', 'pendula', 'FABACEAE', 'Fabales', array['Sombrillo']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza muerta marrón amarillenta. Hojas compuestas, alternas, bipinnadas. Flores péndulas de color amarillo a rojo. Frutos negros, alargados y aplanados.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/parkia_pendula.jpg', array['Maderable', 'Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 1, 'parkia_pendula'),
  ('Parkia velutina', 'Benoist', 'Parkia', 'velutina', 'FABACEAE', 'Fabales', array['Guarango blanco', 'Guarango']::text[], 'Árbol e dosel emergente. Fuste recto. Corteza externa lenticelada con aletones o raíces tabulares. Hojas compuestas alternas con peciolo ferrugíneo. Flores rosadas. Fruto negro, aplanado, pubescente con textura de gamuza.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/parkia_velutina.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Autocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, 'No se realizó', true, true, true, 6, 'parkia_velutina'),
  ('Pera arborea', 'Mutis', 'Pera', 'arborea', 'PERACEAE', 'Malpighiales', array['Gallino']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón rojizo, lenticelada. Corteza interna blanda, color rosado. Olor dulce. Hojas simples, alternas, nerviación acrodoroma. Frutos globosos veres.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pera_arborea.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 1, 'pera_arborea'),
  ('Perebea mollis', '(Poepp. & Endl.) Huber', 'Perebea', 'mollis', 'MORACEAE', 'Rosales', array['Granadillo rojo', 'Palo de vaco', '"Leche chivo"']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón oscuro, estriada. Corteza interna amarilla, dura, con látex blanco. Hojas simples, alternas, pubescentes, ligeramente ferrugíneas. Fruto pubescente, globoso, verde amarillento.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/perebea_mollis.jpg', array['Alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 4, 'perebea_mollis'),
  ('Piptocoma discolor', '(Kunth) Pruski', 'Piptocoma', 'discolor', 'ASTERACEAE', 'Asterales', array['Palonegro']::text[], 'Árbol de áreas abiertas o ecotonos. Corteza viva con betas amarillas y negras. Hojas simples, alternas, con envés blanco (discoloras, glaucas). Flores blancas a crema. Frutos color café.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/piptocoma_discolor.jpg', array['Alimento animal', 'medicinal', 'alimento para abejas']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Pionera', NULL, 'No se realizó', true, true, true, 8, 'piptocoma_discolor'),
  ('Platymiscium pinnatum', '(Jacq.) Dugand', 'Platymiscium', 'pinnatum', 'FABACEAE', 'Fabales', array['Guayacán', 'Guayacán rosado', 'Guayacán amarillo']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón amarillenta. Corteza interna amarilla. Hojas compuestas, opuestas, de foliolos opuestos. Frutos alados con una única semilla amarillenta o crema.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/platymiscium_pinnatum.jpg', array['Medicinal', 'veneno', 'allimento', 'ambiental']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 7, 'platymiscium_pinnatum'),
  ('Pourouma bicolor', 'Mart.', 'Pourouma', 'bicolor', 'URTICACEAE', 'Rosales', array['Caimaron de monte']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón grisácea. Corteza viva amarillenta, exudado hialino que oxida. Hojas simples, o palmeadas, alternas, pubescentes, de envés blanco. Frutos de verde a morado al madurar, de sabor dulce.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pourouma_bicolor.jpg', array['Medicina', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 1, 'pourouma_bicolor'),
