  ('Pouteria baehniana', 'Monach.', 'Pouteria', 'baehniana', 'SAPOTACEAE', 'Ericales', array['Caimo', 'Caimo colorao', 'Caimitillo']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón rojizo, con desprendimiento en placas. Corteza viva marrón amarillento, látex blanco saliendo en puntos. Hojas simples, alternas. Fruto globoso marrón de pulpa dulce.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_baehniana.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 7, 'pouteria_baehniana'),
  ('Pouteria caimito', '(Ruiz & Pav.) Radlk.', 'Pouteria', 'caimito', 'SAPOTACEAE', 'Ericales', array['Caimo Piedra', 'Caimo colorao', '"Caimo"']::text[], 'Árbol de dosel. Fuste recto, cilíndrico o acanalado. Corteza muerta marrón rojiza, escamosa. Corteza viva marrón amarillenta a rojiza. Látex blanco. Flores blancuzcas. Fruto sésil de verde a amarillo al madurar. Semillas negras.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_caimito.jpg', array['Alimento humano', 'alimento animal', 'medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 5, 'pouteria_caimito'),
  ('Pouteria cuspidata', '(A.DC.) Baehni', 'Pouteria', 'cuspidata', 'SAPOTACEAE', 'Ericales', array['Caimitillo', 'Granadillo', 'Caimo balato']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón clara, escamosa. Corteza viva media amarilla, interna marrón rojiza. Látex blanco escaso saliendo en puntos. Hojas simples, alternas, obovadas a elípticas. Flores blancas. Frutos amarillentos al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_cuspidata.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 3, 'pouteria_cuspidata'),
  ('Pouteria glomerata', '(Miq.) Radlk.', 'Pouteria', 'glomerata', 'SAPOTACEAE', 'Ericales', array['Caimo']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón rojiza, escamosa. Corteza viva amarillenta. Látex blanco escaso saliendo en puntos. Hojas simples, alternas, obovadas a elípticas. Frutos amarillentos al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_glomerata.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, false, false, 0, 'pouteria_glomerata'),
  ('Pouteria guianensis', 'Aubl.', 'Pouteria', 'guianensis', 'SAPOTACEAE', 'Ericales', array['Caimo', '"Caimo"', 'Caimo colorado']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón rojiza, escamosa o fisurada. Corteza viva amarillenta. Látex blanco escaso saliendo en puntos. Hojas simples, alternas, obovadas a elípticas. Frutos amarillentos al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_guianensis.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 5, 'pouteria_guianensis'),
  ('Pouteria hispida', 'Eyma', 'Pouteria', 'hispida', 'SAPOTACEAE', 'Ericales', array['"Caimo"', 'Caimo']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón rojiza, escamosa o fisurada. Corteza viva amarillenta. Látex blanco. Hojas simples, alternas, obovadas a elípticas, pubescentes. Frutos pubescentes de verde a amarillo al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_hispida.jpg', array['Alimento']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 2, 'pouteria_hispida'),
  ('Pouteria laevigata', '(Mart.) Radlk.', 'Pouteria', 'laevigata', 'SAPOTACEAE', 'Ericales', array['Caimo piedra']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón rojiza. Latex amarillo o blanco. Hojas agrupadas al final de la rama. Frutos globulares color marrón.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_laevigata.jpg', array['Aliemnto']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'pouteria_laevigata'),
  ('Pouteria procera', '(Mart.) K.Hammer', 'Pouteria', 'procera', 'SAPOTACEAE', 'Ericales', array['Caimitillo', 'Caimo']::text[], 'Árbol de dosel emergente. Fuste recto con raíces tabulares de hasta 2 m. Corteza muerta marrón rojiza, escamosa. Corteza viva rosada con betas rojas. Látex color crema a amarillo. Hojas simples, alternas, elípticas. Fruto amarillo al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pouteria_procera.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, 'No se realizó', true, true, true, 5, 'pouteria_procera'),
  ('Pouteria ucuqui', 'Pires & R.E.Schult.', 'Pouteria', 'ucuqui', 'SAPOTACEAE', 'Ericales', array['Caimo piedra']::text[], NULL, NULL, array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, NULL),
  ('Protium aracouchini', '(Aubl.) Marchand', 'Protium', 'aracouchini', 'BURSERACEAE', 'Sapindales', array['Caraño', '"Caraño"']::text[], 'Árbol de dosel emergente. Fuste recto, corteza viva color amarillo, exudado incoloro que al secarse se convierte en resina. Hojas compuestas imparipinnadas, alternas de foliolos opuestos, con pulvínulos engrosados. Frutos rojos, con arilo blanco de sabor dulce.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/protium_aracouchini.jpg', array['Alimento', 'Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 6, 'protium_aracouchini'),
  ('Pterocarpus officinalis', 'Jacq.', 'Pterocarpus', 'officinalis', 'FABACEAE', 'Fabales', array['Caqueteño/Yema de huevo', 'Caqueteño']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón amarillenta, lenticelada, que desprende en placas grandes. Hojas compuestas, alternas, de foliolos alternos. Frutos alados.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/pterocarpus_officinalis.jpg', array['Medicina', 'Combustible']::text[], 'NT', 'NA', 'Nativa', 'Anemocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 3, 'pterocarpus_officinalis'),
  ('Qualea acuminata', 'Spruce ex Warm.', 'Qualea', 'acuminata', 'VOCHYSIACEAE', 'Myrtales', array['Avichuri', 'Arenillo/Avichure', 'Arenillo']::text[], 'Árbol de dosel emergente. Fuste recto, con raíces tabulares. Corteza muerta marrón. Corteza viva amarillenta con exudado hialino viscoso. Hojas simples, opuestas, elípticas, con glándulas cerca a la base del pecíolo. Flores con pétalos blancos. Fruto en cápsulas trilobuladas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/qualea_acuminata.jpg', array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 4, 'qualea_acuminata'),
  ('Qualea homosepala', 'Ducke', 'Qualea', 'homosepala', 'VOCHYSIACEAE', 'Myrtales', array['Gurre']::text[], 'Árbol de dosel emergente. Fuste recto, con raíces tabulares. Corteza muerta marrón. Corteza viva amarillenta. Hojas simples, opuestas, elípticas, con glándulas cerca a la base del pecíolo. Fruto en cápsulas gruesas trilobuladas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/qualea_homosepala.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 6, 'qualea_homosepala'),
  ('Qualea paraensis', 'Ducke', 'Qualea', 'paraensis', 'VOCHYSIACEAE', 'Myrtales', array['Arenillo', 'Polvillo', 'Avichuri']::text[], 'Árbol de dosel emergente. Fuste recto, con raíces tabulares. Corteza muerta marrón clara, estriada. Corteza viva amarillenta. Hojas simples, opuestas, elípticas, con glándulas cerca a la base del pecíolo. Flores con un pétalo grande, blanco rosáceo con zona central amarilla con rojo alrededor. Fruto en cápsulas gruesas trilobuladas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/qualea_paraensis.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 8, 'qualea_paraensis'),
  ('Samanea saman', '(Jacq.) Merr.', 'Samanea', 'saman', 'FABACEAE', 'Fabales', array['Guarango']::text[], 'Árbol de dosel emergente, de copa amplia. Fuste recto con aletones. Cortea externa marrón oscuro a negro, fisurada en placas que desprenden. Corteza interna amarilla, olor amargo, Hojas compuestas, alternas, con glándulas en el raquis. Flores rosadas. Frutos alargados, aplanados y dehiscentes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/samanea_saman.jpg', array['Alimento animal', 'veneno', 'medicinal', 'ambiental', 'social', 'combustible']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 2, 'samanea_saman'),
  ('Simarouba amara', 'Aubl.', 'Simarouba', 'amara', 'SIMAROUBACEAE', 'Sapindales', array['Marfil', 'Tara, marfil', 'Nogal o Marfil']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón grisácea, fisurada. Corteza viva amarillenta fibrosa, olor amargo. Hojas compuestas, alternas, foliolos opuestos, coriáceos, oblongos. Inflorescencias terminales, flores de pétalos verde claro. Frutos elipsoidales, negruzcos al madurar.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/simarouba_amara.jpg', array['Alimento animal', 'veneno', 'medicinal']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 19, 'simarouba_amara'),
  ('Sin identificar', NULL, 'Sin', 'identificar', NULL, NULL, array['Manguillo']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No se realizó', false, false, true, 0, NULL),
  ('Sloanea floribunda', 'Spruce ex Benth.', 'Sloanea', 'floribunda', 'ELAEOCARPACEAE', 'Oxalidales', array['Poblano']::text[], 'Árbol de dosel emergente. Raíces tabulares, fuste recto amarillento, con lenticelas circulares , corteza muerta con desprendimiento en placas. Hojas simples, alternas, con doble pulvínulo, estípulas caducas. Inflorescencias axilares. Fruto seco en cápsula loculicida.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/sloanea_floribunda.jpg', array['Ambiental', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'sloanea_floribunda'),
  ('Sloanea guianensis', '(Aubl.) Benth.', 'Sloanea', 'guianensis', 'ELAEOCARPACEAE', 'Oxalidales', array['Caimitillo']::text[], 'Árbol de dosel emergente. Raíces tabulares. Fuste recto. Corteza externa amarillenta. Hojas simples, alternas, con doble pulvínulo, margen de entero a serrado. Fruto seco en capsula loculicida color rojizo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/sloanea_guianensis.jpg', array['Ambiental', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'sloanea_guianensis'),
  ('Sloanea rufa', 'Planch. ex Benth.', 'Sloanea', 'rufa', 'ELAEOCARPACEAE', 'Oxalidales', array['Copal incienso']::text[], 'Árbol de dosel emergente. Raíces tabulares. Fuste recto. Corteza externa lecticelada color amarillento. Corteza viva amarilla, muy aromático a canela. Hojas simples, alternas, ovadas, con ápice redondeado, peciolo con doble pulvínulo. Frutos secos en cápsula loculicida, con exocarpo espinoso. Cuatro semillas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/sloanea_rufa.jpg', array['Alimento', 'maderable']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'sloanea_rufa'),
  ('Spondias mombin', 'L.', 'Spondias', 'mombin', 'ANACARDIACEAE', 'Sapindales', array['Hobo', 'Ciruelo', '"Jobo"']::text[], 'Árbol de tallo recto, de dosel emergente. Corteza muerta marón escamosa, fisurada con protuberancias longitudinales, corteza viva rosada con betas blancas. Resina incolora. Hojas compuestas, alternas de foliolos opuestos imparipinnados. Inflorescencias en panículas. Frutos ovados a elípticos, madurando amarillo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/spondias_mombin.jpg', array['Combustible', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 3, 'spondias_mombin'),
  ('Sterculia apeibophylla', 'Ducke', 'Sterculia', 'apeibophylla', 'MALVACEAE', 'Malvales', array['Zapotolongo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón grisáceo. Corteza interna marrón amarillento. Hojas simples, alternas ferrugíneas de consistencia bulada, pubescentes, con doble pulvínulo y tres nervios saliendo de la base. Fruto de gran tamaño con indumento interno.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/sterculia_apeibophylla.jpg', array['Ambiental']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'sterculia_apeibophylla'),
  ('Sterculia kayae', 'P.E.Berry', 'Sterculia', 'kayae', 'MALVACEAE', 'Malvales', array['Zapote rojo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón oscuro. Corteza interna amarillenta, arenosa, muy dura. Hojas simples alternas, con doble pulvínulo, glabras, agrupadas al final de las ramas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/sterculia_kayae.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'sterculia_kayae'),
  ('Tapirira guianensis', 'Aubl.', 'Tapirira', 'guianensis', 'ANACARDIACEAE', 'Sapindales', array['Cedrillo, fresno', 'Cedrillo', 'Sangretoro']::text[], 'Árbol de dosel, fuste cilíndrico, corteza viva con betas blancas y rosadas. Hojas compuestas, alternas, de foliolos imparipinnados. Inflorescencias axilares. Frutos en drupas que maduran de color morado, la semilla de color blanco embebida en una pulpa translucida.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/tapirira_guianensis.jpg', array['Medicina', 'combustible', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', 'RECALCITRANTE', 'Agua 2 horas', true, true, true, 14, 'tapirira_guianensis'),
  ('Terminalia amazonia', '(J.F.Gmel.) Exell', 'Terminalia', 'amazonia', 'COMBRETACEAE', 'Myrtales', array['Ahumado chipo', 'Ahumado muchilero']::text[], 'Árbol de dosel emergente, fuste con aletones, recto, corteza muerta fisurada color marrón oscuro. Corteza interna amarillenta. Ramas con crecimiento simpodial (formado Y), arquitectura tipo pagoda. Hojas simples, alternas, ovadas y agrupadas al final de las ramas. Flores verdes blancuzcas. Frutos con alas longitudinales.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/terminalia_amazonia.jpg', array['Medicinal']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 3, 'terminalia_amazonia'),
  ('Terminalia congesta', '(Ducke) Gere & Boatwr.', 'Terminalia', 'congesta', 'COMBRETACEAE', 'Myrtales', array['Fono negro', 'Fono colorao', 'Fono']::text[], 'Árbol de dosel emergente. Fuste recto, corteza muerta marrón que despende en tiras largas. Corteza viva amarillenta fibrosa. Hojas simples, alternas, ovadas, agrupadas al final de las ramas. Frutos verdes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/terminalia_congesta.jpg', array['Ambiental']::text[], 'NE', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Intermedia', 'no encontré en literatura', 'Cortar punta de la semilla,Lavado con hipoclorito,dejar en agua 5 días', true, true, true, 5, 'terminalia_congesta'),
  ('Terminalia lucida', 'Hoffmanns. ex Mart.', 'Terminalia', 'lucida', 'COMBRETACEAE', 'Myrtales', array['Ahumado chipo', 'Ahumado escobo']::text[], 'Árbol de dosel emergente, fuste con aletones, recto, corteza muerta fisurada color marrón oscuro. Corteza interna amarillenta. Ramas con crecimiento simpodial (formado Y), arquitectura tipo pagoda. Hojas simples, alternas, ovadas y agrupadas al final de las ramas. Frutos alados.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/terminalia_lucida.jpg', array['Maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 3, 'terminalia_lucida'),
  ('Terminalia parvifolia', '(Ducke) Gere & Boatwr.', 'Terminalia', 'parvifolia', 'COMBRETACEAE', 'Myrtales', array['Ahumado pajarito', 'Ahumado muchilero']::text[], 'Árbol de dosel emergente. Fuste recto con aletones, corteza muerta fisurada color marrón oscuro. Corteza interna amarillenta. Ramas con crecimiento simpodial (formado Y), arquitectura en pagoda. Hojas simples, alternas, con pubescencia ferrugínea. Inflorescencia en espiga. Fruto alado.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/terminalia_parvifolia.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 6, 'terminalia_parvifolia'),
  ('Terminalia tetraphylla', '(Aubl.) Gere & Boatwr.', 'Terminalia', 'tetraphylla', 'COMBRETACEAE', 'Myrtales', array['Ahumado verde']::text[], 'Árbol de dosel emergente. Fuste recto con aletones, corteza muerta fisurada color marrón oscuro. Corteza interna amarillenta. Ramas con crecimiento simpodial (formado Y), arquitectura en pagoda. Hojas simples, alternas. Inflorescencia en espiga. Fruto s verdes.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/terminalia_tetraphylla.jpg', array['Medicina', 'Maderable']::text[], 'LC', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 1, 'terminalia_tetraphylla'),
  ('Theobroma grandiflorum', NULL, 'Theobroma', 'grandiflorum', NULL, NULL, array['copoazú']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'RECALCITRANTE', 'No se realizó', false, false, true, 0, NULL),
  ('Theobroma subincanum', 'Mart.', 'Theobroma', 'subincanum', 'MALVACEAE', 'Malvales', array['Copoazu silvestre', 'Copoazu montuno', 'Cacao copoazu']::text[], 'Árbol de sotobosque. Fuste recto. Corteza externa marrón. Hojas simples, alternas, con envés blanco a ferroso, con doble pulvínulo. Frutos amarillo a café liso.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/theobroma_subincanum.jpg', array['Medicina', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Intermedia', NULL, NULL, true, true, false, 4, 'theobroma_subincanum'),
  ('Trattinnickia burserifolia', 'Mart.', 'Trattinnickia', 'burserifolia', 'BURSERACEAE', 'Sapindales', array['Caraño', 'Caraño blanco', 'Carraño']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza viva amarillenta. Exudado hialino, aromático a mongo verde. Hojas compuestas, imparipinnadas, de foliolos opuestos. Inflorescencia en panículas terminales. Frutos en drupa globosa color morado a negro, semilla rugosa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/trattinnickia_burserifolia.jpg', array['Alimento', 'Medicina']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 6, 'trattinnickia_burserifolia'),
  ('Trattinnickia lancifolia', '(Cuatrec.) Daly', 'Trattinnickia', 'lancifolia', 'BURSERACEAE', 'Sapindales', array['Caraño']::text[], 'Árbol de dosel emergente. Fuste recto corteza externa lenticelada. Corteza viva amarillenta a rojiza. Exudado hialino tardío que se convierte en resina blanca, aromático a trementina. Hojas compuestas, imparipinnadas, opuestas, de foliolos opuestos. Inflorescencia en panículas terminales. Frutos en drupa globosa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/trattinnickia_lancifolia.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 4, 'trattinnickia_lancifolia'),
  ('Trattinnickia rhoifolia', 'Willd.', 'Trattinnickia', 'rhoifolia', 'BURSERACEAE', 'Sapindales', array['Caraño', 'Cascabel', 'Gurre']::text[], 'Árbol de dosel emergente. Fuste recto, corteza muerta marrón, en placas, lecticelada. Corteza viva amarillenta, con exudado hialino tardío que se convierte en resina blanca, muy aromático a trementina. Hojas compuestas, opuestas, imparipinnadas, de foliolos opuestos. Frutos en drupa globosa.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/trattinnickia_rhoifolia.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila (Entomófila)', 'Tardia', NULL, NULL, true, true, false, 5, 'trattinnickia_rhoifolia'),
  ('Trichilia tuberculata', '(Triana & Planch.) C.DC.', 'Trichilia', 'tuberculata', 'MELIACEAE', 'Sapindales', array['Fono blanco']::text[], 'Cedron Árbol de dosel, Fuste recto. Corteza externa marrón, lenticelada que desprende en placas. Corteza interna amarilla, olor dulce. Hojas compuestas, alternas, de foliolos opuestos, peciolo triangular. Frutos con exocarpo amarillo, semilla con arilo rojo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/trichilia_tuberculata.jpg', array['Alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'trichilia_tuberculata'),
  ('Virola carinata', '(Spruce ex Benth.) Warb.', 'Virola', 'carinata', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro blanco']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón grisácea, rugosa. Corteza interna amarillenta. Exudado incoloro que oxida. Hojas simples, alternas con envés discoloro, peciolo y vena central ferrugínea. Inflorescencias axilares. Frutos bivalvados, de cubierta lisa, arilo naranja a rojo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_carinata.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'virola_carinata'),
  ('Virola coelhoi', 'W.A.Rodrigues', 'Virola', 'coelhoi', 'MYRISTICACEAE', 'Magnoliales', array['Sangre toro negro']::text[], 'Árbol de dosel. Fuste recto. Corteza externa maro oscuro, con placas que desprenden. Corteza interna rojiza, exudado rojo acuoso. Hojas imples, alternas, ovadas a elípticas, con envés ferrugíneo. Frutos bivalvados.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_coelhoi.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'virola_coelhoi'),
  ('Virola duckei', 'A.C.Sm.', 'Virola', 'duckei', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro rojo']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón amarillenta, fisurada. Corteza interna amarilla, con exudado rojo acuoso. Hojas simples, alternas, con envés blanco, venas ferrugíneas. Fruto bivalvado.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_duckei.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'virola_duckei'),
  ('Virola elongata', '(Benth.) Warb.', 'Virola', 'elongata', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro rosado', 'Sangretoro rojo', 'Sangretoro blanco']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón rojiza, fisurada. Corteza viva rojiza con vetas amarillentas y exudado rojo acuoso, usualmente con olor a trementina. Hojas simples, alternas, elípticas con envés blanco. Frutos bivalvados de cubierta ferrugínea. Semilla parcialmente recubierta con arilo color naranja.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_elongata.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 10, 'virola_elongata'),
  ('Virola multinervia', 'Ducke', 'Virola', 'multinervia', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro lengua de potro']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón, escamosa, fisurada. Corteza viva amarillenta con betas rojas, exudado rojo acuoso. Hojas simples, alternas con envés blanquecino, peciolos y vena central ferrugíneas. Fruto de 2 valvas, con tomento ferrugíneo y semilla con arilo rojo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_multinervia.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 1, 'virola_multinervia'),
  ('Virola obovata', 'Ducke', 'Virola', 'obovata', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro', 'Sangretoro rosado']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón amarillenta, fisurada. Corteza interna amarilla con exudado hialino que oxida. Hojas simples, alternas, con envés blanquecino. Inflorescencias axilares. Frutos de 2 valvas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_obovata.jpg', array['Ambiental']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 8, 'virola_obovata'),
  ('Virola sebifera', 'Aubl.', 'Virola', 'sebifera', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro rosado', 'Sangretoro blanco']::text[], 'Árbol de dosel. Fuste recto. Corteza muerta marrón, fisurada. Corteza viva marrón rojizo, con exudado rojo acuoso y ligeramente aromático. Arquitectura tipo pagoda. Hojas simples, alternas con envés blanquecino. Pecíolos, ramillas y frutos con tomento ferrugíneo. Semilla con arilo amarillo.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_sebifera.jpg', array['Medicinal', 'alimento']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 3, 'virola_sebifera'),
  ('Virola theiodora', '(Spruce ex Benth.) Warb.', 'Virola', 'theiodora', 'MYRISTICACEAE', 'Magnoliales', array['Sangretoro', 'Barbasco o ahumado']::text[], 'Árbol de dosel. Fuste recto. Corteza externa marrón rojizo, con placas que desprende. Corteza interna roja, exudado rojo acuoso. Hojas simples, alternas, discoloras, ovado-elípticas. Frutos con 2 valvas.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/virola_theiodora.jpg', array['Veneno', 'medicinal', 'sociales']::text[], 'LC', 'NA', 'Nativa', 'Zoocoria', 'Zoófila', 'Tardia', NULL, NULL, true, true, false, 13, 'virola_theiodora'),
  ('Vitex orinocensis', NULL, 'Vitex', 'orinocensis', NULL, NULL, array['Ahumado micho/Flor morada']::text[], NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'no encontré en literatura', 'Agua 3 horas', false, false, true, 0, NULL),
  ('Vochysia grandis', 'Mart.', 'Vochysia', 'grandis', 'VOCHYSIACEAE', 'Myrtales', array['Gomo', 'Gomo arracacho', 'Gomo cucharo']::text[], 'Árbol de dosel emergente. Fuste recto. Corteza externa marrón grisáceo, lenticelada. Corteza interna marrón amarillento, arenosa, dura. Hojas simples, opuestas, en verticilos de tres, agrupadas al final de las ramas. Flores amarillas. Frutos cafés.', 'https://lbxysovesmbgesxooghw.supabase.co/storage/v1/object/public/species-photos/vochysia_grandis.jpg', array['Ambiental']::text[], 'NE', 'NA', 'Nativa', 'Anemocoria', 'Zoófila', 'Intermedia', NULL, NULL, true, true, false, 8, 'vochysia_grandis'),
